    "film_tahun"
  ],
  "properties": {
    "linkedin_caption": {
      "type": "string",
      "description": "Bahasa Inggris, 120-200 kata, diakhiri URL EN"
    },
    "ig_caption": {
      "type": "string",
      "description": "Bahasa Indonesia, 30-60 kata, diakhiri \"Link lengkapnya di bio\""
    },
    "fb_caption": {
      "type": "string",
      "description": "Bahasa Indonesia, 150-250 kata, diakhiri \"Baca lengkapnya: <URL ID>\""
    },
    "hashtags": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "maksimal 5 hashtag huruf kecil"
    },
    "image_series": {
      "type": "string",
      "description": "Satu kalimat Inggris pengikat kelima gambar"
    },
    "accent": {
      "type": "string",
      "description": "Satu warna #RRGGBB dari KELUARGA BIRU (hue 180-265: teal, biru, indigo). Dipakai sebagai latar chip berteks putih, jadi harus cukup pekat — kontras minimal 4.5:1. Di luar rentang itu diganti biru brand"
    },
    "layout": {
      "type": "string",
      "enum": [
        "blok-bawah",
        "pias-bawah",
        "tengah"
      ],
      "description": "blok-bawah = foto penuh + blok teks di bawah; pias-bawah = foto atas + panel gelap bawah; tengah = judul di tengah foto"
